/**
 * API reference builder for LLM prompts.
 * Generates concise figma.* method listings and code-generation prompts.
 */
import { registry } from './toolRegistry.js';
import { DESIGN_RULES } from './designRules.js';
/**
 * Build a concise API reference string from the tool registry.
 * Uses the registry directly (not searchRegistry) to get all entries without capping.
 */
export function buildApiReference() {
    const lines = ['## Available figma.* Methods\n'];
    // Group by category
    const grouped = new Map();
    for (const entry of registry) {
        const list = grouped.get(entry.category) || [];
        list.push(entry);
        grouped.set(entry.category, list);
    }
    for (const [category, methods] of grouped) {
        lines.push(`### ${category.toUpperCase()}`);
        for (const m of methods) {
            const requiredParams = Object.entries(m.parameters)
                .filter(([, v]) => v.required)
                .map(([k, v]) => `${k}: ${v.type}`)
                .join(', ');
            const optionalCount = Object.keys(m.parameters).length -
                Object.values(m.parameters).filter(v => v.required).length;
            const optionalNote = optionalCount > 0 ? ` (+${optionalCount} optional)` : '';
            lines.push(`- \`${m.name}(${requiredParams ? `{ ${requiredParams} }` : ''})\`${optionalNote} -> ${m.returns}`);
            lines.push(`  ${m.description.split('\n')[0]}`);
        }
        lines.push('');
    }
    return lines.join('\n');
}
/**
 * Build a full code-generation prompt for the LLM.
 * Includes rules, API reference, optional context, and the task.
 */
export function buildCodeGenPrompt(task, context) {
    const sections = [];
    sections.push(`You are a Figma code generator. Output ONLY valid JavaScript code that uses the figma.* API.

## Rules
- Output raw executable JavaScript code ONLY. No markdown fences, no explanations, no comments.
- All figma.* methods are async -- always use await.
- Text nodes inside auto-layout MUST have layoutSizingHorizontal: "FILL".
- Do not use emojis anywhere -- not in node names, text content, or console output.
- Use return to send back the final result (usually the created node or array of nodes).
- Use console.log() for debug output.
- If you need to reference a created node's ID, store the result: const node = await figma.createFrame({...}); then use node.id.
- Catch errors only when you can handle them meaningfully. Let unexpected errors propagate.`);
    sections.push(buildApiReference());
    // Add key design rules (condensed)
    sections.push(`## Design Rules (condensed)
${DESIGN_RULES.text}
`);
    if (context) {
        sections.push(`## Context from previous steps
${context}`);
    }
    sections.push(`## Task
${task}`);
    return sections.join('\n\n');
}
/**
 * Build a planning prompt that asks the LLM to return a JSON array of step descriptions.
 */
export function buildPlanPrompt(task) {
    return `You are a Figma design planner. Break down the following design task into sequential steps.

## Rules
- Output ONLY a valid JSON array of strings. No markdown fences, no explanations.
- Each string is a clear, self-contained description of one step.
- Steps should be in logical order (create containers first, then children).
- Keep each step focused: one logical unit (e.g., one component, one section).
- Aim for 2-8 steps. Don't over-decompose simple tasks.
- Each step should produce at least one visible Figma node.

## Example output
["Create a 400x300 card frame with white background and 16px padding","Add a title text 'Dashboard' with fontSize 24 and Bold weight to the card","Add a subtitle text 'Welcome back' with fontSize 14 and gray color below the title"]

## Task
${task}`;
}
